"""Optional adapter to the external ``connes-cvs`` package.

Purpose
-------
Use Akiva Groskin's independent Connes--van Suijlekom implementation as a
cross-validation oracle for shared low-level Weil ingredients.  It is *not*
the canonical Atlas proof engine and its trigonometric Galerkin matrix is not
entrywise identical to Atlas's polynomial/parity/bubble Gram blocks.

Evidence rule
-------------
External results are diagnostic/cross-check evidence until independently
regenerated by Atlas's own interval certifier.  Finite-matrix eigenpair
certificates from connes-cvs may be stored as external E1 artifacts, but they
must not silently promote an Atlas theorem/certificate.
"""
from __future__ import annotations

from dataclasses import dataclass, asdict
from importlib import import_module
from importlib.metadata import PackageNotFoundError, version
from typing import Any, Iterable


EXPECTED_PACKAGE = "connes-cvs"
TESTED_VERSION = "0.3.1"


class ConnesCVSUnavailable(RuntimeError):
    """Raised when the optional external oracle is not installed."""


@dataclass(frozen=True)
class DependencyInfo:
    available: bool
    version: str | None
    tested_version: str
    role: str = "external_cross_validation_oracle"
    canonical_proof_engine: bool = False

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


def dependency_info() -> DependencyInfo:
    try:
        installed = version(EXPECTED_PACKAGE)
    except PackageNotFoundError:
        return DependencyInfo(False, None, TESTED_VERSION)
    return DependencyInfo(True, installed, TESTED_VERSION)


def _mods():
    try:
        kernels = import_module("connes_cvs.kernels")
        operator = import_module("connes_cvs.operator")
        validation = import_module("connes_cvs.validation")
    except ImportError as exc:
        raise ConnesCVSUnavailable(
            "Install optional oracle with `pip install connes-cvs==0.3.1` "
            "or from a reviewed source commit."
        ) from exc
    return kernels, operator, validation


def h0_transform(beta, L):
    """External stable evaluation of H0(beta;L)=int_0^L exp(i beta x) dx."""
    kernels, _, _ = _mods()
    return kernels.stable_A(beta, L)


def linear_taper_transform(beta, L):
    """External stable transform of (1-x/L) on [0,L].

    Note: this is not Atlas's quadratic bubble transform x(L-x).
    """
    kernels, _, _ = _mods()
    return kernels.stable_B(beta, L)


def h_plus(tau, dps: int = 80):
    """External archimedean multiplier Re psi(1/4+i tau/2)-log(pi)."""
    _, operator, _ = _mods()
    return operator.h_plus(tau, dps)


def prime_power_data(c: int):
    """Return external (n, log n, Lambda(n)/sqrt(n)) tuples up to c."""
    _, operator, _ = _mods()
    data, primes = operator.prime_powers_up_to(c)
    return data, primes


def build_trigonometric_galerkin(c, N: int = 8, T: int = 84, dps: int = 80):
    """Build the external CvS trigonometric Galerkin matrix.

    This matrix lives in a different basis from Atlas polynomial blocks.
    Compare spectral/quadratic-form invariants only after an explicit basis or
    projection map has been defined.
    """
    _, operator, _ = _mods()
    return operator.build_galerkin_matrix(c=c, N=N, T=T, dps=dps)


def finite_eigenpair_certificate(Q, eigenvector, eigenvalue, dps: int = 80):
    """Run connes-cvs's finite symmetric-matrix Arb residual certificate."""
    _, _, validation = _mods()
    return validation.arb_eigenpair_residual_bound(
        Q, eigenvector, eigenvalue, dps=dps
    )


def crosscheck_h0(samples: Iterable[tuple[Any, Any]], dps: int = 80) -> list[dict]:
    """Cross-check stable_A against the same integral evaluated by mpmath.

    This is a diagnostic consistency check, not an Atlas certificate.
    """
    kernels, _, _ = _mods()
    mp = import_module("mpmath")
    old_dps = mp.mp.dps
    mp.mp.dps = dps
    out = []
    try:
        for beta, L in samples:
            beta_m = mp.mpf(beta)
            L_m = mp.mpf(L)
            ext = kernels.stable_A(beta_m, L_m)
            if beta_m == 0:
                ref = mp.mpc(L_m, 0)
            else:
                ref = (mp.e ** (1j * beta_m * L_m) - 1) / (1j * beta_m)
            out.append({
                "beta": mp.nstr(beta_m, 30),
                "L": mp.nstr(L_m, 30),
                "abs_error": mp.nstr(abs(ext - ref), 20),
            })
    finally:
        mp.mp.dps = old_dps
    return out
